    function setApprovalDate(context) {
        const { newRecord, oldRecord } = context;
        const { id } = newRecord;
        try {
            // Quotes don't have approval dates
            if (newRecord.type != record.Type.SALES_ORDER) {
                return;
            }
            const orderstatus = newRecord.getValue('orderstatus');
            // Order in Pending Approval
            if (orderstatus == 'A') {
                return;
            }
            // I set this field as a text field so that it doesn't break the system when a string is passed to it instead of a date object, unfortunately, this has caused people to come after me in the past and flex as if they were somehow superior.
            const custbody_nk_approval_date = String(newRecord.getValue('custbody_nk_approval_date'));
            // In case the field was manually set to a string value which can't represent a date
            if (String(new Date(custbody_nk_approval_date)) == 'Invalid Date') {
                newRecord.setValue({ fieldId: 'custbody_nk_approval_date', value: '' });
            }
            if (custbody_nk_approval_date) { // Should use the first time an order is approved so no need to double check the field value for the most recent approval
                return new Date(custbody_nk_approval_date);
            }
            // If using the approve button or if setting the status field in edit mode
            else if (context.type == context.UserEventType.APPROVE || ['', 'A'].includes(String(oldRecord?.getValue('orderstatus') || '')) && orderstatus == 'B') {
                // Will this depend on the time zone of the user?
                const approvalDate = new Date();
                newRecord.setValue({ fieldId: 'custbody_nk_approval_date', value: new Date(approvalDate).toLocaleString() });
                return approvalDate;
            }
            // For old orders that were approved before this script was written or in case an order was approved without running SuiteScript
            else {
                const approvalDateSystemNotes = query.runSuiteQL({
                    query: `
                    SELECT 
                        TO_CHAR(date, 'DS TS') as date
                    FROM 
                        systemnote
                    WHERE recordtypeid = -30
                    AND recordid = ${id}
                    AND field = 'TRANDOC.KSTATUS'
                    AND newvalue = 'Pending Fulfillment'
                    ORDER BY
                        id
                `
                }).asMappedResults()[0]?.date;
                if (approvalDateSystemNotes) {
                    const approvalDate = new Date(String(approvalDateSystemNotes));
                    newRecord.setValue({ fieldId: 'custbody_nk_approval_date', value: approvalDate.toLocaleString() });
                    return approvalDate;
                }
                else {
                    // If no system notes exist for an approved order, it was most likely created in pending fulfillment in which case the approval date should match the createddate
                    const createddate = (newRecord.getValue('createddate') || new Date());
                    const approvalDate = new Date(createddate);
                    newRecord.setValue({ fieldId: 'custbody_nk_approval_date', value: approvalDate.toLocaleString() });
                    return approvalDate;
                }
            }
        }
        catch (e) {
            log.error('@setApprovalDate', { id, message: e.message });
        }
    }
